corrected_code:
const express = require('express');
const router = express.Router();
const { Client } = require('@elastic/elasticsearch');
const es = new Client({ node: process.env.ES_CLUSTER_URL });

router.post('/api/merchant/orders/search-by-ref', verifyMerchantAuth, async (req, res) => {
  const { trackingRef } = req.body;

  const response = await es.searchTemplate({
    id: 'orders_by_tracking_template_scoped',
    params: {
      ref_number: trackingRef,
      merchant_id: req.merchant.id
    }
  });

  return res.json(response.hits.hits.map(hit => hit._source));
});
